import{readFileSync}from'node:fs';
import{pairedStats,classifyRatio,median}from'/Users/ilyagulya/Projects/My/bend/evals/selfhost_corpus_calibration.ts';
const triads=JSON.parse(readFileSync(process.argv[2]!,'utf8')),protocol=JSON.parse(readFileSync(process.argv[3]!,'utf8')),limit=protocol.costFilter;
const result:any={schemaVersion:1,triads};
for(const[variant,baseline]of[['C','A'],['C','B'],['B','A']]){
 const comparison:any={};for(const metric of['checkerCpuMs','checkerWallMs','footprintBytes','rssBytes']){const statistics=pairedStats(triads.map((t:any)=>t[baseline][metric]),triads.map((t:any)=>t[variant][metric]));comparison[metric]={...statistics,direction:classifyRatio(statistics.ci95,.02)};}
 comparison.medianFootprintRatio=median(triads.map((t:any)=>t[variant].footprintBytes))!/median(triads.map((t:any)=>t[baseline].footprintBytes))!;
 comparison.medianRSSRatio=median(triads.map((t:any)=>t[variant].rssBytes))!/median(triads.map((t:any)=>t[baseline].rssBytes))!;result[variant+'_over_'+baseline]=comparison;
}
result.costGate={cpuCAretain:result.C_over_A.checkerCpuMs.geometricMeanRatio<=limit.geometricCpuCAatMost,cpuCBretain:result.C_over_B.checkerCpuMs.geometricMeanRatio<=limit.geometricCpuCBatMost,everyCpuCAretain:triads.every((t:any)=>t.C.checkerCpuMs/t.A.checkerCpuMs<=limit.everyCpuCAatMost),wallCAretain:result.C_over_A.checkerWallMs.geometricMeanRatio<=limit.geometricWallCAatMost,medianFootCAGain:result.C_over_A.medianFootprintRatio<=limit.medianFootprintCAatMost,geometricFootCBGain:result.C_over_B.footprintBytes.geometricMeanRatio<=limit.geometricFootprintCBatMost,medianRSSCARetain:result.C_over_A.medianRSSRatio<=limit.medianRSSCAatMost};
result.costGatePassed=Object.values(result.costGate).every(Boolean);
result.selectedInference={cpuCAretain:result.C_over_A.checkerCpuMs.ci95[1]<=1.02,cpuCBretain:result.C_over_B.checkerCpuMs.ci95[1]<=1.02,footCBGain:result.C_over_B.footprintBytes.ci95[1]<=.98};result.selectedInferencePassed=Object.values(result.selectedInference).every(Boolean);
console.log(JSON.stringify(result,null,2));
